  const[restaurant,setRestaurant]=useState(null),[foods,setFoods]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[attempt,setAttempt]=useState(0),[search,setSearch]=useState(''),[category,setCategory]=useState('All dishes');
  useEffect(()=>{const controller=new AbortController();let active=true;setLoading(true);setError('');setRestaurant(null);setFoods([]);Promise.all([api.get(`/restaurants/${id}`,{signal:controller.signal}),api.get('/foods',{params:{restaurantId:id},signal:controller.signal})]).then(([restaurantResponse,foodResponse])=>{if(active){setRestaurant(restaurantResponse.data);setFoods(foodResponse.data)}}).catch(requestError=>{if(active&&!controller.signal.aborted)setError(errorText(requestError))}).finally(()=>{if(active)setLoading(false)});return()=>{active=false;controller.abort()}},[id,attempt]);
