  const restaurantId=restaurantIdOf(cart[0]?.restaurantId);
  const signature=cart.map(line=>line._id).sort().join('|');
  useEffect(()=>{if(!signature){setRecords([]);setLoading(false);setError('');return}const controller=new AbortController();let active=true;setLoading(true);setError('');const request=restaurantId?api.get('/foods',{params:{restaurantId,includeUnavailable:true},signal:controller.signal}).then(response=>response.data):Promise.all(cart.map(line=>api.get(`/foods/${line._id}`,{signal:controller.signal}).then(response=>response.data).catch(requestError=>{if(requestError.response?.status===404)return null;throw requestError})));request.then(items=>{if(active)setRecords(items.filter(Boolean))}).catch(requestError=>{if(active&&!controller.signal.aborted)setError(errorText(requestError))}).finally(()=>{if(active)setLoading(false)});return()=>{active=false;controller.abort()}},[restaurantId,signature,attempt]);
