function Profile(){const{user,setUser,notify}=useStore(),nav=useNavigate(),[name,setName]=useState(user?.name||''),[phone,setPhone]=useState(user?.phone||''),[address,setAddress]=useState(user?.address||''),[error,setError]=useState('');useEffect(()=>{if(!user)nav('/login')},[user]);async function save(e){e.preventDefault();try{const r=await api.put('/users/profile',{name,phone,address});setUser(r.data.user);localStorage.setItem('foodiego_user',JSON.stringify(r.data.user));notify('Your profile is up to date')}catch(e){setError(errorText(e))}}return <div className="pageShell"><div className="pageIntro"><span className="eyebrow">YOUR LITTLE CORNER</span><h1>My <em>profile.</em></h1><p>Keep your delivery details close at hand.</p></div><form className="formCard profileForm" onSubmit={save}><div className="profileHeading"><span className="profileAvatar">{user?.name?.[0]}</span><div><h2>{user?.name}</h2><p>{user?.email}</p></div></div><label>Name<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Phone<input type="tel" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Add a phone number"/></label><label>Delivery address<input value={address} onChange={e=>setAddress(e.target.value)} placeholder="Add your delivery address"/></label>{error&&<ErrorBox text={error}/>}<button className="button">Save changes <ArrowRight size={16}/></button></form></div>}
